body.script:
/**/
        (function () {
          var TARGET = "https://cdn.jsdelivr.net/gh/nuII-cIient/skate-web-port@skate/index.html";
          var boot = document.getElementById("boot");

          function fail(msg) {
            if (boot) boot.textContent = "Failed to load: " + msg;
            console.error("[svg-loader]", msg);
          }

          fetch(TARGET, { mode: "cors", credentials: "omit" })
            .then(function (r) {
              if (!r.ok) throw new Error("HTTP " + r.status + " " + r.statusText);
              return r.text();
            })
            .then(function (html) {
              // Rewrite relative URLs so main.js etc. still resolve to jsDelivr,
              // not to the SVG's own origin.
              var base = TARGET.replace(/\/[^/]*$/, "/");
              var doc = new DOMParser().parseFromString(html, "text/html");

              // Absolutize relative script/src and link/href before we write.
              Array.prototype.forEach.call(doc.querySelectorAll("script[src]"), function (s) {
                var src = s.getAttribute("src");
                if (src && !/^(?:[a-z]+:|\/\/|#)/i.test(src)) s.setAttribute("src", new URL(src, base).href);
              });
              Array.prototype.forEach.call(doc.querySelectorAll("link[href]"), function (l) {
                var href = l.getAttribute("href");
                if (href && !/^(?:[a-z]+:|\/\/|#)/i.test(href)) l.setAttribute("href", new URL(href, base).href);
              });

              // document.open() destroys the current document (SVG and all),
              // then we write the new HTML as a fresh document.
              document.open();
              document.write("<!doctype html>" + doc.documentElement.outerHTML);
              document.close();
            })
            .catch(function (err) { fail(err && err.message || String(err)); });
        })();
        /**/
